const AS_CFG={url:'https://tikjmiyrhkcjrxjylmqb.supabase.co',key:'sb_publishable_clr5P9USk7b63MajJmmr9A_Iz0wi_0F',version:'2026.08.16-assignment2'};
const AS_SESSION_KEY='fleet_mvp_session_v2';
function asSession(){try{return JSON.parse(localStorage.getItem(AS_SESSION_KEY)||'null')}catch{return null}}
function asSave(s){if(s)localStorage.setItem(AS_SESSION_KEY,JSON.stringify(s))}
async function asRefresh(){const s=asSession();if(!s?.refresh_token)throw new Error('Сессия истекла. Войдите снова.');const r=await fetch(`${AS_CFG.url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:AS_CFG.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.access_token)throw new Error(d.message||d.msg||'Сессия истекла. Войдите снова.');d.obtained_at=Date.now();asSave(d);return d}
async function asRpc(name,params={},retry=true){let s=asSession();if(!s?.access_token)throw new Error('Нужно войти в систему.');let r=await fetch(`${AS_CFG.url}/rest/v1/rpc/${encodeURIComponent(name)}`,{method:'POST',headers:{apikey:AS_CFG.key,Authorization:`Bearer ${s.access_token}`,'Content-Type':'application/json'},body:JSON.stringify(params)});if(r.status===401&&retry){s=await asRefresh();r=await fetch(`${AS_CFG.url}/rest/v1/rpc/${encodeURIComponent(name)}`,{method:'POST',headers:{apikey:AS_CFG.key,Authorization:`Bearer ${s.access_token}`,'Content-Type':'application/json'},body:JSON.stringify(params)})}if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.message||x.error||`HTTP ${r.status}`)}const t=await r.text();return t?JSON.parse(t):null}
function ash(v=''){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function asToast(text,type=''){let h=document.querySelector('.toast-host');if(!h){h=document.createElement('div');h.className='toast-host';document.body.appendChild(h)}const e=document.createElement('div');e.className=`toast ${type}`;e.textContent=text;h.appendChild(e);setTimeout(()=>e.remove(),3400)}
function asError(m=''){const s=String(m||'');const rules=[[/Vehicle has unfinished waybill/i,'Сначала завершите путевой лист этой машины.'],[/Driver has unfinished waybill on another vehicle/i,'У водителя есть незавершённый путевой лист на другой машине.'],[/Driver lacks required license category/i,'Категория водительского удостоверения не подходит.'],[/license.*expired|license validity|license.*missing/i,'У водителя нет действующего удостоверения. Обновите данные водителя.'],[/Admin role required/i,'Действие доступно только администратору.']];const x=rules.find(([r])=>r.test(s));return x?x[1]:s}
function ensureAsHint(form){let el=form.querySelector('.as-context');if(!el){el=document.createElement('div');el.className='as-context demo-note';const driver=form.elements.driver_id?.closest('.field');driver?.appendChild(el)}return el}
async function hydrateAssignment(form){if(!form||form.dataset.asPatch)return;form.dataset.asPatch=AS_CFG.version;const vehicle=form.elements.vehicle_id,driver=form.elements.driver_id,submit=form.querySelector('button[type="submit"]'),hint=ensureAsHint(form);if(!vehicle||!driver||!submit)return;let currentCtx=null;let seq=0;
  function applyDriverState(){const id=driver.value;const d=(currentCtx?.drivers||[]).find(x=>x.id===id);if(!d){hint.textContent=currentCtx?.selected_vehicle?.assignment_blocked?currentCtx.blocking_message:'Выберите водителя.';submit.disabled=true;submit.textContent=currentCtx?.selected_vehicle?.assignment_blocked?'Закрепление недоступно':'Закрепить';return}if(d.same_vehicle){hint.textContent='Этот водитель уже закреплён за выбранной машиной.';submit.disabled=true;submit.textContent='Уже закреплён';return}submit.disabled=false;if(d.currently_assigned){hint.innerHTML=`Сейчас водитель закреплён за <strong>${ash(d.currently_assigned)}</strong>. При закреплении здесь прежнее назначение будет закрыто.`;submit.textContent='Переназначить'}else{hint.textContent='Водитель подходит и свободен для закрепления.';submit.textContent='Закрепить'}}
  async function loadContext(){const token=++seq;const vehicleId=vehicle.value;if(!vehicleId){driver.innerHTML='<option value="">Сначала выберите машину</option>';driver.disabled=true;submit.disabled=true;hint.textContent='После выбора машины система покажет только доступных водителей.';return null}driver.disabled=true;submit.disabled=true;hint.textContent='Проверяем категорию, срок удостоверения и незавершённые ПЛ…';try{const x=await asRpc('get_assignment_form',{p_vehicle_id:vehicleId});if(token!==seq)return null;currentCtx=x;const sv=x.selected_vehicle||{};const req=(sv.required_categories||[]).join(', ')||'без ограничений';if(sv.assignment_blocked){driver.innerHTML='<option value="">Закрепление недоступно</option>';driver.disabled=true;submit.disabled=true;submit.textContent='Закрепление недоступно';hint.textContent=`Требуется: ${req}. ${x.blocking_message||'Сначала завершите незавершённый ПЛ.'}`;return x}const drivers=x.drivers||[];driver.innerHTML='<option value="">Выберите водителя</option>'+drivers.map(d=>`<option value="${ash(d.id)}">${ash(d.rank?`${d.rank} `:'')}${ash(d.label)} · ${(d.categories||[]).join(', ')}</option>`).join('');driver.disabled=drivers.length===0;const same=drivers.find(d=>d.same_vehicle);if(same)driver.value=same.id;hint.textContent=drivers.length?`Требуется: ${req}. Доступно водителей: ${drivers.length}.`:`Нет водителя с действующим удостоверением и нужной категорией (${req}).`;applyDriverState();return x}catch(e){currentCtx=null;driver.innerHTML='<option value="">Не удалось загрузить водителей</option>';driver.disabled=true;submit.disabled=true;hint.textContent=asError(e.message);asToast(asError(e.message),'error');return null}}
  vehicle.addEventListener('change',loadContext);driver.addEventListener('change',applyDriverState);
  form.addEventListener('submit',async e=>{if(form.dataset.asValidated==='1'){form.dataset.asValidated='';return}e.preventDefault();e.stopImmediatePropagation();if(!vehicle.value||!driver.value){asToast(!vehicle.value?'Выберите машину.':'Выберите доступного водителя.','error');return}submit.disabled=true;try{const fresh=await asRpc('get_assignment_form',{p_vehicle_id:vehicle.value});const d=(fresh.drivers||[]).find(x=>x.id===driver.value);if(fresh.selected_vehicle?.assignment_blocked||!d){currentCtx=fresh;await loadContext();asToast(fresh.blocking_message||'Водитель больше недоступен. Список обновлён.','error');return}if(d.same_vehicle){currentCtx=fresh;applyDriverState();asToast('Водитель уже закреплён за этой машиной.');return}form.dataset.asValidated='1';form.requestSubmit()}catch(err){asToast(asError(err.message),'error')}finally{if(form.dataset.asValidated!=='1')submit.disabled=false}},true);
  await loadContext()}
let asPending=false;function asScan(){asPending=false;hydrateAssignment(document.getElementById('assignmentForm'))}function asSchedule(){if(asPending)return;asPending=true;queueMicrotask(asScan)}new MutationObserver(asSchedule).observe(document.documentElement,{childList:true,subtree:true});asSchedule();